public java.util.Map<Integer, Integer> frequency(int[] nums) {
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int x : nums) {
        freq.put(x, freq.getOrDefault(x, 0) + 1);
    }
    return freq;
}

